arguments.content:
:root {
  --primary-color: #02838D;
  --primary-hover: #016b74;
  --text-dark: #231F20;
  --text-light: #4b5563;
  --bg-light: #F9FAFB;
  --bg-white: #FFFFFF;
  --accent-color: #F28C28; /* Amber/Coral */
  --accent-hover: #d9781f;
  --border-color: #E5E7EB;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  color: var(--text-dark);
  background-color: var(--bg-white);
  line-height: 1.5;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-dark);
  margin-bottom: 0.5rem;
}

h1 { font-size: 2.5rem; }
h2 { font-size: 2rem; margin-bottom: 1.5rem;}
h3 { font-size: 1.5rem; }
h4 { font-size: 1.25rem; }

.section-title {
  font-size: 2rem;
  margin-bottom: 2rem;
  text-align: left;
}

p {
  color: var(--text-light);
  margin-bottom: 1rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
  font-size: 1rem;
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}
.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-accent {
  background-color: var(--accent-color);
  color: white;
}
.btn-accent:hover {
  background-color: var(--accent-hover);
}

.btn-outline {
  background-color: transparent;
  border: 2px solid var(--primary-color);
  color: var(--primary-color);
}
.btn-outline:hover {
  background-color: var(--primary-color);
  color: white;
}

/* Topbar / Credibility Stats Ticker */
.topbar {
  background-color: var(--text-dark);
  color: white;
  padding: 0.5rem 0;
  overflow: hidden;
  position: relative;
  font-size: 0.875rem;
  font-weight: 500;
  display: flex;
  align-items: center;
}

.ticker-wrap {
  width: 100%;
  overflow: hidden;
  white-space: nowrap;
}

.ticker {
  display: inline-block;
  animation: ticker 30s linear infinite;
}

.ticker-item {
  display: inline-flex;
  align-items: center;
  padding: 0 2rem;
}
.ticker-item i {
  color: var(--primary-color);
  margin-right: 0.5rem;
}

@keyframes ticker {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* Header */
header {
  border-bottom: 1px solid var(--border-color);
  background: var(--bg-white);
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 80px;
}

.logo {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--primary-color);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* Navigation */
.main-nav {
  display: flex;
  gap: 2rem;
  height: 100%;
}

.nav-item {
  position: relative;
  display: flex;
  align-items: center;
  cursor: pointer;
  font-weight: 600;
  color: var(--text-dark);
  height: 100%;
}

.nav-item:hover, .nav-item.active {
  color: var(--primary-color);
}

.nav-item i {
  margin-left: 0.25rem;
  font-size: 1.25rem;
  transition: transform 0.2s;
}

.nav-item.active i {
  transform: rotate(180deg);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.header-actions .subscribe {
  color: var(--primary-color);
  font-weight: 600;
}
.header-actions .signin {
  color: var(--text-dark);
  font-weight: 600;
}

/* Mega Menu Dropdown */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 0;
  width: 100vw;
  background-color: var(--bg-white);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  box-shadow: var(--shadow-md);
  padding: 2rem 0;
  display: none;
  z-index: 50;
  max-height: calc(100vh - 80px);
  overflow-y: auto;
}

.mega-menu.active {
  display: block;
}

.mega-menu-inner {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.mega-menu-list h4 {
  margin-bottom: 1rem;
  color: var(--primary-color);
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 0.5rem;
}

.mega-menu-list ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.mega-menu-list a {
  color: var(--text-dark);
  font-weight: 500;
}
.mega-menu-list a:hover {
  color: var(--primary-color);
}

/* Hero Section */
.hero-section {
  padding: 3rem 0;
}

.hero-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 2rem;
}

.hero-main {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background-color: var(--text-dark);
  color: white;
  min-height: 400px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 3rem;
  background-size: cover;
  background-position: center;
}

.hero-overlay {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(to top, rgba(35, 31, 32, 0.9) 0%, rgba(35, 31, 32, 0.2) 100%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 600px;
}

.category-label {
  display: inline-block;
  background-color: var(--primary-color);
  color: white;
  padding: 0.25rem 0.75rem;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1rem;
}

.hero-main h1 {
  color: white;
  margin-bottom: 1rem;
}

.hero-main p {
  color: #e5e7eb;
  font-size: 1.125rem;
  margin-bottom: 0;
}

.badge {
  position: absolute;
  top: 1.5rem;
  right: 1.5rem;
  background-color: var(--accent-color);
  color: white;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  font-weight: 700;
  font-size: 0.875rem;
  line-height: 1.2;
  z-index: 2;
  box-shadow: var(--shadow-md);
}

/* Trending */
.trending-sidebar {
  background-color: var(--bg-light);
  padding: 1.5rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
}

.trending-sidebar h3 {
  border-bottom: 2px solid var(--border-color);
  padding-bottom: 0.75rem;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.trending-list {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.trending-item {
  display: flex;
  gap: 1rem;
}

.trending-number {
  font-size: 2rem;
  font-weight: 800;
  color: var(--border-color);
  line-height: 1;
}

.trending-content h4 {
  font-size: 1rem;
  margin-bottom: 0.25rem;
  line-height: 1.4;
}
.trending-content h4 a:hover {
  color: var(--primary-color);
}
.trending-meta {
  font-size: 0.75rem;
  color: var(--primary-color);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Newsletter CTA */
.newsletter-section {
  background-color: var(--primary-color);
  color: white;
  padding: 4rem 0;
  text-align: center;
}

.newsletter-section h2 {
  color: white;
}

.newsletter-section p {
  color: rgba(255, 255, 255, 0.9);
  max-width: 600px;
  margin: 0 auto 2rem;
  font-size: 1.125rem;
}

.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 0 auto;
  gap: 0.5rem;
}

.newsletter-form input {
  flex: 1;
  padding: 0.75rem 1rem;
  border: 2px solid transparent;
  border-radius: var(--radius-full);
  font-size: 1rem;
  outline: none;
}
.newsletter-form input:focus {
  border-color: var(--accent-color);
}

.privacy-note {
  display: block;
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 1rem;
}

/* Health Topics Carousel */
.health-topics-section {
  padding: 4rem 0;
  background-color: var(--bg-white);
}

.carousel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
}

.carousel-controls {
  display: flex;
  gap: 0.5rem;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
  color: var(--text-dark);
}
.carousel-btn:hover {
  background: var(--bg-light);
  border-color: var(--primary-color);
  color: var(--primary-color);
}

.topics-carousel-wrap {
  overflow: hidden;
  position: relative;
}

.topics-carousel {
  display: flex;
  gap: 2rem;
  transition: transform 0.3s ease;
}

.topic-card {
  min-width: calc((100% - 10rem) / 6);
  text-align: center;
  cursor: pointer;
}
.topic-card:hover .topic-img {
  transform: scale(1.05);
  box-shadow: var(--shadow-md);
}
.topic-card:hover h4 {
  color: var(--primary-color);
}

.topic-img-wrap {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto 1rem;
  overflow: hidden;
  border: 4px solid var(--bg-light);
}

.topic-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.topic-card h4 {
  font-size: 1rem;
  font-weight: 600;
  transition: color 0.2s;
}

/* Tools Section */
.tools-section {
  padding: 4rem 0;
  background-color: var(--bg-light);
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
}

.tool-card {
  background: var(--bg-white);
  border-radius: var(--radius-lg);
  padding: 2.5rem;
  border: 1px solid var(--border-color);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
}

.tool-card-icon {
  width: 48px;
  height: 48px;
  background-color: rgba(2, 131, 141, 0.1);
  color: var(--primary-color);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
}

.tools-list {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  flex: 1;
}

.tools-list-item {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem;
  border-radius: var(--radius-md);
  background-color: var(--bg-light);
  transition: background-color 0.2s;
}
.tools-list-item:hover {
  background-color: #f3f4f6;
}

.tools-list-item i {
  color: var(--primary-color);
  font-size: 1.25rem;
  margin-top: 0.125rem;
}

.tools-list-item-content h5 {
  font-size: 1rem;
  margin-bottom: 0.25rem;
}
.tools-list-item-content p {
  font-size: 0.875rem;
  margin-bottom: 0;
}

.tool-card-footer {
  margin-top: 2rem;
}

/* Recommended Reads */
.recommended-section {
  padding: 4rem 0;
}

.tabs {
  display: flex;
  gap: 1rem;
  margin-bottom: 2.5rem;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1rem;
  overflow-x: auto;
  white-space: nowrap;
}

.tab-btn {
  background: none;
  border: none;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-light);
  cursor: pointer;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-full);
  transition: all 0.2s;
}

.tab-btn:hover {
  color: var(--primary-color);
  background-color: var(--bg-light);
}

.tab-btn.active {
  color: white;
  background-color: var(--primary-color);
}

.articles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 2rem;
}

.article-card {
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
  height: 100%;
}
.article-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.article-card:hover h4 {
  color: var(--primary-color);
}

.article-img-wrap {
  aspect-ratio: 16/9;
  overflow: hidden;
  background: var(--bg-light);
}

.article-img-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s;
}
.article-card:hover .article-img-wrap img {
  transform: scale(1.05);
}

.article-content {
  padding: 1.5rem 0;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.article-content h4 {
  font-size: 1.125rem;
  line-height: 1.4;
  margin-bottom: auto;
  transition: color 0.2s;
}

/* Trust Pillars */
.trust-section {
  padding: 5rem 0;
  background-color: var(--text-dark);
  color: white;
  text-align: center;
}

.trust-section h2 {
  color: white;
  margin-bottom: 3rem;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.trust-card {
  padding: 1.5rem;
}

.trust-icon {
  width: 64px;
  height: 64px;
  background-color: rgba(2, 131, 141, 0.2);
  color: var(--primary-color);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  margin: 0 auto 1.5rem;
}

.trust-card h4 {
  color: white;
  margin-bottom: 1rem;
}
.trust-card p {
  color: #9ca3af;
  font-size: 0.9375rem;
}

/* Featured Programs & Videos */
.featured-section {
  padding: 4rem 0;
  background-color: var(--bg-white);
}

.featured-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}

.program-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 3/4;
}

.program-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.program-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0) 60%);
  display: flex;
  align-items: flex-end;
  padding: 1.5rem;
}

.program-overlay h4 {
  color: white;
  margin: 0;
  font-size: 1.125rem;
}

.video-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 16/9;
  margin-bottom: 1rem;
}

.play-btn {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 48px;
  height: 48px;
  background-color: rgba(255,255,255,0.9);
  color: var(--primary-color);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  z-index: 2;
  transition: transform 0.2s;
}
.video-card:hover .play-btn {
  transform: translate(-50%, -50%) scale(1.1);
}

/* Footer */
footer {
  background-color: var(--bg-light);
  border-top: 1px solid var(--border-color);
  padding: 4rem 0 2rem;
}

.footer-top {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 4rem;
  margin-bottom: 3rem;
}

.footer-newsletter p {
  margin-bottom: 1.5rem;
  font-size: 0.9375rem;
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.footer-links ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footer-links a {
  color: var(--text-light);
  font-size: 0.9375rem;
}
.footer-links a:hover {
  color: var(--primary-color);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
}

.legal-text {
  font-size: 0.75rem;
  color: #6b7280;
  max-width: 800px;
}

.social-links {
  display: flex;
  gap: 1rem;
}

.social-links a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background-color: var(--border-color);
  color: var(--text-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}
.social-links a:hover {
  background-color: var(--primary-color);
  color: white;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-grid, .tools-grid { grid-template-columns: 1fr; }
  .trust-grid, .featured-grid { grid-template-columns: repeat(2, 1fr); }
  .topic-card { min-width: calc((100% - 6rem) / 4); }
  .footer-top { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .mega-menu-inner { grid-template-columns: 1fr 1fr; }
  .main-nav { display: none; } /* Add hamburger for mobile in real app */
  .topic-card { min-width: calc((100% - 4rem) / 3); }
}

@media (max-width: 480px) {
  .trust-grid, .featured-grid { grid-template-columns: 1fr; }
  .topic-card { min-width: calc((100% - 2rem) / 2); }
  .footer-links { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; text-align: center; }
}

document.addEventListener('DOMContentLoaded', () => {
  // 1. Mega Menu Toggle
  const navItems = document.querySelectorAll('.nav-item.has-dropdown');
  const megaMenu = document.getElementById('mega-menu');

  navItems.forEach(item => {
    item.addEventListener('click', (e) => {
      e.preventDefault();

      // Close others if open
      navItems.forEach(nav => {
        if (nav !== item) nav.classList.remove('active');
      });

      const isActive = item.classList.toggle('active');

      if (isActive) {
        megaMenu.classList.add('active');
      } else {
        megaMenu.classList.remove('active');
      }
    });
  });

  // Close mega menu when clicking outside
  document.addEventListener('click', (e) => {
    if (!e.target.closest('header')) {
      navItems.forEach(nav => nav.classList.remove('active'));
      megaMenu.classList.remove('active');
    }
  });

  // 2. Health Topics Carousel
  const topicsCarousel = document.getElementById('topics-carousel');
  const btnPrev = document.getElementById('carousel-prev');
  const btnNext = document.getElementById('carousel-next');

  if (topicsCarousel && btnPrev && btnNext) {
    let scrollPosition = 0;
    const scrollAmount = 300; // pixels to scroll

    btnNext.addEventListener('click', () => {
      // Basic implementation - in reality we'd calculate max scroll
      const maxScroll = topicsCarousel.scrollWidth - topicsCarousel.clientWidth;
      if (scrollPosition < maxScroll) {
        scrollPosition += scrollAmount;
        if (scrollPosition > maxScroll) scrollPosition = maxScroll;
        topicsCarousel.style.transform = `translateX(-${scrollPosition}px)`;
      }
    });

    btnPrev.addEventListener('click', () => {
      if (scrollPosition > 0) {
        scrollPosition -= scrollAmount;
        if (scrollPosition < 0) scrollPosition = 0;
        topicsCarousel.style.transform = `translateX(-${scrollPosition}px)`;
      }
    });
  }

  // 3. Recommended Reads Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  // Using generic mock functionality for tabs
  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      tabBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      // In a real app we would filter or fetch articles here
      // For the prototype we just trigger a tiny opacity animation
      const articlesGrid = document.querySelector('.articles-grid');
      if (articlesGrid) {
        articlesGrid.style.opacity = '0';
        setTimeout(() => {
          articlesGrid.style.opacity = '1';
        }, 150);
      }
    });
  });

  // 4. Newsletter Form
  const newsletterForms = document.querySelectorAll('.newsletter-form');
  newsletterForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = form.querySelector('input');
      const btn = form.querySelector('button');

      if (input.value) {
        const originalText = btn.innerHTML;
        btn.innerHTML = 'Subscribed!';
        btn.classList.add('btn-primary');
        input.value = '';

        setTimeout(() => {
          btn.innerHTML = originalText;
          btn.classList.remove('btn-primary');
        }, 3000);
      }
    });
  });
});
